/**
 * Fix broken sidebar navigation links generated by pydata-sphinx-theme
 * in singlehtml mode.
 *
 * The theme produces hrefs like "#document-installation#how-to-install"
 * (double fragment) instead of "#how-to-install". This script strips the
 * "document-<name>#" prefix so the browser navigates to the correct anchor.
 */
document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("a.nav-link, a.reference.internal").forEach(function (a) {
        var href = a.getAttribute("href");
        if (href && href.indexOf("#") !== href.lastIndexOf("#")) {
            // Keep only the last fragment: "#doc-name#section" → "#section"
            a.setAttribute("href", "#" + href.split("#").pop());
        }
    });
});
